from backend import Backend, Duplicate
from service import save
backend = Backend()
result = save(backend, 'key', 'original')
print('direct creation:', repr(result))
assert result['created'] is None
try:
    save(backend, 'key', 'replacement')
except Duplicate:
    print('direct duplicate: Duplicate propagated')
else:
    raise AssertionError('Expected Duplicate')
assert backend.rows['key'] == 'original'
print('original value preserved:', repr(backend.rows['key']))
class Offline:
    def put(self, key, value):
        raise OSError('offline')
try:
    save(Offline(), 'key', 'value')
except OSError:
    print('direct operational failure: OSError propagated')
else:
    raise AssertionError('Expected OSError')
PY"

